const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const rows = db.prepare('SELECT * FROM ts_reminders').all();
rows.forEach((r, i) => {
  const gap = r.reminder_timestamp - r.creation_timestamp;
  const hours = Math.floor(gap / 3600);
  const mins = Math.floor((gap % 3600) / 60);
  const secs = gap % 60;
  console.log('---');
  console.log('Reminder #' + (i+1) + ': ' + r.content);
  console.log('  ID: ' + r.reminder_id);
  console.log('  creation_timestamp: ' + r.creation_timestamp + ' (' + new Date(r.creation_timestamp * 1000).toISOString() + ')');
  console.log('  reminder_timestamp: ' + r.reminder_timestamp + ' (' + new Date(r.reminder_timestamp * 1000).toISOString() + ')');
  console.log('  gap: ' + gap + ' seconds (' + hours + 'h ' + mins + 'm ' + secs + 's)');
});
db.close();
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const crypto = require('crypto');

const now = Math.floor(Date.now() / 1000);
const gap = 41400; // 11h 30m
const reminderTs = now + gap;
const id = crypto.randomUUID();

db.prepare(
  'INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude) VALUES (?, ?, ?, ?, ?, ?)'
).run(id, 'Lunch with Jordan tomorrow at 12:30.', now, reminderTs, null, null);

console.log('New reminder created:');
console.log('  ID: ' + id);
console.log('  content: Lunch with Jordan tomorrow at 12:30.');
console.log('  creation_timestamp: ' + now + ' (' + new Date(now * 1000).toISOString() + ')');
console.log('  reminder_timestamp: ' + reminderTs + ' (' + new Date(reminderTs * 1000).toISOString() + ')');
console.log('  gap applied: ' + gap + ' seconds (11h 30m)');

db.close();
"

